create table if not exists public.subcategories (id uuid primary key default gen_random_uuid(), category_id uuid not null references public.categories(id) on delete cascade, name text not null, slug text not null, is_active boolean not null default true, sort_order integer not null default 0, unique(category_id,slug));
create table if not exists public.brands (id uuid primary key default gen_random_uuid(), name text not null unique, slug text not null unique, is_active boolean not null default true, sort_order integer not null default 0);
create table if not exists public.brand_subcategories (brand_id uuid not null references public.brands(id) on delete cascade, subcategory_id uuid not null references public.subcategories(id) on delete cascade, primary key(brand_id,subcategory_id));
insert into public.subcategories(category_id,name,slug,sort_order) select c.id,v.name,v.slug,v.sort_order from public.categories c join (values ('groceries','Dairy & eggs','dairy-eggs',10),('groceries','Packaged foods','packaged-foods',20),('groceries','Beverages','beverages',30),('fashion','Men''s fashion','mens-fashion',10),('fashion','Women''s fashion','womens-fashion',20),('footwear','Men''s footwear','mens-footwear',10),('footwear','Women''s footwear','womens-footwear',20),('electronics','Smartphones','smartphones',10),('electronics','Headphones','headphones',20),('electronics','Laptops','laptops',30),('home-kitchen','Cookware','cookware',10),('personal-care','Skin care','skin-care',10),('personal-care','Hair care','hair-care',20)) v(category_slug,name,slug,sort_order) on c.slug=v.category_slug on conflict(category_id,slug) do nothing;
insert into public.brands(name,slug,sort_order) values ('Amul','amul',10),('Britannia','britannia',20),('Nike','nike',30),('Adidas','adidas',40),('Samsung','samsung',50),('Apple','apple',60),('boAt','boat',70),('Lenovo','lenovo',80),('Prestige','prestige',90),('Nivea','nivea',100),('Dove','dove',110) on conflict(slug) do nothing;
alter table public.shops add column if not exists primary_category_id uuid references public.categories(id) on delete set null;
alter table public.products add column if not exists category_id uuid references public.categories(id) on delete set null, add column if not exists subcategory_id uuid references public.subcategories(id) on delete set null, add column if not exists brand_id uuid references public.brands(id) on delete set null;
alter table public.subcategories enable row level security; alter table public.brands enable row level security; alter table public.brand_subcategories enable row level security;
drop policy if exists "active subcategories are public" on public.subcategories;
drop policy if exists "active brands are public" on public.brands;
drop policy if exists "brand subcategories are public" on public.brand_subcategories;
create policy "active subcategories are public" on public.subcategories for select to anon,authenticated using(is_active);
create policy "active brands are public" on public.brands for select to anon,authenticated using(is_active);
create policy "brand subcategories are public" on public.brand_subcategories for select to anon,authenticated using(true);
